// One finished turn: what it cost, in tokens, and what it did
export type Turn = {
  // Input tokens that did not come from the cache
  input: number
  // Tokens generated by the model
  output: number
  // Input tokens served by the prompt cache
  cacheRead: number
  // Input tokens written into the prompt cache
  cacheWrite: number
  // Tool calls during the turn
  tools: number
  // Duration of the turn, in seconds
  seconds: number
  // true for the turn of a subagent
  isSubagent: boolean
}

declare module 'claude-code' {
  interface PluginState {
    'compteur-escale': {
      turns: Turn[]
      refusedBookings: number
    }
  }
}
